package com.starlight.greetings.application;
import com.starlight.greetings.web.ApiException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Propagation; import org.springframework.transaction.annotation.Transactional;
@Service public class RequestRateLimiter {private final JdbcTemplate jdbc;public RequestRateLimiter(JdbcTemplate jdbc){this.jdbc=jdbc;}@Transactional(propagation=Propagation.REQUIRES_NEW,noRollbackFor=ApiException.class) public void consume(String scope,String subject,int max){String key=digest(scope+":"+subject);Integer attempts=jdbc.queryForObject("insert into auth_attempts(key_hash,attempts,window_started_at) values(?,1,now()) on conflict(key_hash) do update set attempts=case when auth_attempts.window_started_at<now()-interval '15 minutes' then 1 else auth_attempts.attempts+1 end,window_started_at=case when auth_attempts.window_started_at<now()-interval '15 minutes' then now() else auth_attempts.window_started_at end returning attempts",Integer.class,key);if(attempts!=null&&attempts>max)throw new ApiException(HttpStatus.TOO_MANY_REQUESTS,"RATE_LIMITED","잠시 후 다시 시도해 주세요.");}public void clear(String scope,String subject){jdbc.update("delete from auth_attempts where key_hash=?",digest(scope+":"+subject));}private String digest(String s){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
